def extract_min_max(test_tup, K):
    """Write a function to extract maximum and minimum k elements in the given tuple.

    Return a tuple containing the ``K`` smallest elements followed by the
    ``K`` largest elements, each in ascending order. If ``2 * K`` covers
    the whole input, the sorted input is returned without duplicating the
    overlapping elements.
    """
    if K < 0:
        raise ValueError("K must be non-negative")
    if K == 0:
        return ()
    sorted_tup = sorted(test_tup)
    if 2 * K >= len(sorted_tup):
        return tuple(sorted_tup)
    return tuple(sorted_tup[:K] + sorted_tup[-K:])
